  var fusOn = (s === 'fusion' || s === 'vaporization' || s === 'done');
  var vapOn = (s === 'vaporization' || s === 'done');
  gFus.opacity(s === 'idle' || fusOn ? 1 : 0.25);
  gVap.opacity(s === 'idle' || vapOn ? 1 : 0.25);
  gSub.opacity(1);

  // running total — hidden entirely while idle
  if (s === 'idle') {
    gTotal.hide();
  } else {
    var yT = ySolid, label = '';
    if (!direct) {
      if (s === 'fusion') { yT = yLiquid; label = 'ΔH_fus'; }
      else { yT = yGas; label = 'ΔH_fus + ΔH_vap'; }
    } else {
      yT = yGas; label = 'ΔH_sub';
    }
    gTotal.show();
    totalLine.plot(axisX - 14, ySolid, axisX - 14, yT);
    totalTick.plot(axisX - 22, yT, axisX - 6, yT);
    totalTxt.text(label).move(axisX - 26, yT - 8);
  }

  document.getElementById('stepPathState').textContent = 'Path progress: ' + s;
}

