var totalTxt = gTotal.text('').font({ size: 12, family: 'sans-serif', fill: '#e67e22' })
  .attr({ 'text-anchor': 'end' }).move(axisX - 26, ySolid - 8);
gTotal.hide();

// popups
gSub.css('cursor', 'pointer').on('click', function () {
  showPopup('Sublimation', 'Direct sublimation carries the system straight from Solid to Gas in one step, costing ΔH_sub.');
});
gFus.css('cursor', 'pointer').on('click', function () {
  showPopup('Fusion', 'Melting Solid into Liquid costs the small enthalpy of fusion, ΔH_fus.');
});
gVap.css('cursor', 'pointer').on('click', function () {
  showPopup('Vaporization', 'Boiling Liquid into Gas costs the much larger enthalpy of vaporization, ΔH_vap.');
});
gTotal.css('cursor', 'pointer').on('click', function () {
  showPopup('Running total', 'The orange marker tracks the accumulated enthalpy along the two-step path. After both steps it reaches the Gas line: ΔH_fus + ΔH_vap = ΔH_sub.');
});

// ---- state rendering ----
function render() {
  var direct = state.pathView === 'direct';
  var s = state.stepPath;

  // SVG.js v3: use show()/hide() — .visible(bool) is a getter-only no-op
  if (direct) { gSub.show(); gFus.hide(); gVap.hide(); }
  else { gSub.hide(); gFus.show(); gVap.show(); }

  // Default (idle) state matches the source: all arrows at full opacity.
  // Dimming only applies while stepping through the sequence.
  var fusOn = (s === 'fusion' || s === 'vaporization' || s === 'done');
  var vapOn = (s === 'vaporization' || s === 'done');
  gFus.opacity(s === 'idle' || fusOn ? 1 : 0.25);
  gVap.opacity(s === 'idle' || vapOn ? 1 : 0.25);
  gSub.opacity(1);

  // running total — hidden entirely while idle
  if (s === 'idle') {
    gTotal.hide();
  } else {
    var yT = ySolid, label = '';
    if (!direct) {
      if (s === 'fusion') { yT = yLiquid; label = 'ΔH_fus'; }
      else { yT = yGas; label = 'ΔH_fus + ΔH_vap'; }
    } else {
      yT = yGas; label = 'ΔH_sub';
    }
    gTotal.show();
    totalLine.plot(axisX - 14, ySolid, axisX - 14, yT);
    totalTick.plot(axisX - 22, yT, axisX - 6, yT);
    totalTxt.text(label).move(axisX - 26, yT - 8);
  }

  document.getElementById('stepPathState').textContent = 'Path progress: ' + s;
}

// ---- interactions ----
function update_pathView(v) {
  state.pathView = v;
  render();
}
var stepOrder = ['idle', 'fusion', 'vaporization', 'done'];
function setStepPath(v) {
  state.stepPath = v;
  render();
}
function trigger_stepPath() {
  var i = stepOrder.indexOf(state.stepPath);
  setStepPath(stepOrder[(i + 1) % stepOrder.length]);
}

// ---- demo step player ----
var demoSteps = [
  {
    title: 'Two-step path',
    narration: 'The Solid–Liquid gap is much smaller than the Liquid–Gas gap. Begin the two-step path: melting solid into liquid costs only the small fusion enthalpy.',
    state: { pathView: 'two', stepPath: 'fusion' }
  },
  {
    title: 'Add vaporization',
    narration: 'Now the vaporization arrow lights and the running total climbs the remaining large gap to the Gas line — the accumulated energy from both steps is complete.',
    state: { pathView: 'two', stepPath: 'done' }
  },
  {
    title: 'Compare with direct sublimation',
    narration: 'Switching to the direct path replaces the two stacked arrows with one long sublimation arrow — it spans exactly the same height, proving ΔH_sub = ΔH_fus + ΔH_vap.',
    state: { pathView: 'direct', stepPath: 'done' }
  }
];
var stepIdx = -1;
function applyStep(i) {
  stepIdx = i;
  var st = demoSteps[i];
  document.getElementById('pathViewInput').value = st.state.pathView;
  update_pathView(st.state.pathView);
  setStepPath(st.state.stepPath);
  document.getElementById('demoNarration').textContent = st.narration;
  document.getElementById('stepLabel').textContent = (i + 1) + '/3: ' + st.title;
}
function nextStep() { if (stepIdx < demoSteps.length - 1) applyStep(stepIdx + 1); }
function prevStep() {
  if (stepIdx > 0) applyStep(stepIdx - 1);
  else {
    stepIdx = -1;
    document.getElementById('pathViewInput').value = 'two';
    update_pathView('two');
    setStepPath('idle');
    document.getElementById('demoNarration').textContent = 'Three energy levels: Solid, Liquid, Gas. Use the controls or the step player to compare paths.';
    document.getElementById('stepLabel').textContent = 'Start';
  }
}

render();
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: Enthalpy is a state function, so the energy for sublimation equals the sum of the fusion and vaporization enthalpies along the two-step path between the same solid and gas states.
KEY INSIGHT (what students should walk away understanding): Because enthalpy depends only on the initial and final states, the energy of sublimation must equal the sum of fusion plus vaporization — ΔH_sub = ΔH_fus + ΔH_vap.
DEMO STEPS: 4 guided steps — implement the step player in #ui

