userContent.text:
Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<p id="demoNarration" style="margin:0;font-size:10px;max-width:180px">All arrows are visible at once: the long Sublimation ΔH_sub arrow on the left and the stacked Fusion + Vaporization arrows on the right. The two-step path is emphasized; the direct arrow is dimmed but present.</p>
<div style="display:flex;gap:4px;align-items:center">
  <button onclick="prevStep()">◀</button>
  <span id="stepLabel">1/4: Both paths at a glance</span>
  <button onclick="nextStep()">▶</button>
</div>
<label>Emphasized path:
  <select id="pathViewInput" onchange="update_pathView(this.value)">
    <option value="two" selected>Two-step: fusion + vaporization</option>
    <option value="direct">Direct sublimation</option>
  </select>
</label>
<button id="stepPathInput" onclick="trigger_stepPath()">Step through phase changes</button>
<span id="stepPathState" style="font-size:10px">Path progress: idle</span>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
var W = 600, H = 450;
draw.viewbox(0, 0, W, H);

var ySolid = 380, yLiquid = 300, yGas = 70;
var axisX = 55, lineX0 = 65, lineX1 = 555;
var xSub = 250, xStep = 380;

var state = { pathView: 'two', stepPath: 'idle' };

// ---- static: Energy axis ----
draw.line(axisX, 420, axisX, 15).stroke({ color: '#000', width: 2.5 });
draw.polygon((axisX - 6) + ',24 ' + (axisX + 6) + ',24 ' + axisX + ',8').fill('#000');
draw.text('Energy').font({ size: 17, family: 'sans-serif' })
  .center(20, 220).rotate(-90, 20, 220);

// ---- static: level lines + labels ----
function level(y, label) {
  draw.line(lineX0, y, lineX1, y).stroke({ color: '#2e5be6', width: 5 });
  draw.text(label).font({ size: 17, family: 'sans-serif' })
    .attr({ 'text-anchor': 'end' }).move(lineX1, y - 26);
}
level(ySolid, 'Solid');
level(yLiquid, 'Liquid');
level(yGas, 'Gas');

// ---- arrow helper ----
function redArrow(g, x, y0, y1) {
  g.line(x, y0, x, y1 + 12).stroke({ color: '#c0392b', width: 6 });
  g.polygon((x - 9) + ',' + (y1 + 14) + ' ' + (x + 9) + ',' + (y1 + 14) + ' ' + x + ',' + (y1 - 4))
    .fill('#c0392b');
}

// math label with proper subscript via tspan, e.g. ΔH with sub
function mathLabel(g, sub, x, y) {
  var t = g.text(function (add) {
    add.tspan('ΔH').font({ size: 16, family: 'sans-serif' });
    add.tspan(sub).font({ size: 11, family: 'sans-serif' }).dy(5);
  });
  t.move(x, y);
  return t;
}

// ---- sublimation arrow (direct path) — always drawn ----
var gSub = draw.group();
redArrow(gSub, xSub, ySolid, yGas);
gSub.text('Sublimation').font({ size: 16, family: 'sans-serif' }).move(xSub - 105, yLiquid + 12);
mathLabel(gSub, 'sub', xSub - 96, yLiquid + 37);

// ---- two-step arrows — always drawn ----
var gFus = draw.group();
redArrow(gFus, xStep, ySolid, yLiquid);
gFus.text('Fusion').font({ size: 16, family: 'sans-serif' }).move(xStep + 22, ySolid - 42);
mathLabel(gFus, 'fus', xStep + 22, ySolid - 20);

var gVap = draw.group();
redArrow(gVap, xStep, yLiquid, yGas);
gVap.text('Vaporization').font({ size: 16, family: 'sans-serif' }).move(xStep + 22, yGas + 105);
mathLabel(gVap, 'vap', xStep + 52, yGas + 130);

// ---- running-total marker on the Energy axis ----
var gTotal = draw.group();
var totalLine = gTotal.line(axisX - 14, ySolid, axisX - 14, ySolid)
  .stroke({ color: '#e67e22', width: 3 });
var totalTick = gTotal.line(axisX - 22, ySolid, axisX - 6, ySolid)
  .stroke({ color: '#e67e22', width: 3 });
var totalTxt = gTotal.text('').font({ size: 12, family: 'sans-serif', fill: '#e67e22' })
  .attr({ 'text-anchor': 'end' }).move(axisX - 26, ySolid - 8);
gTotal.hide();

// popups
gSub.css('cursor', 'pointer').on('click', function () {
  showPopup('Sublimation', 'Direct sublimation carries the system straight from Solid to Gas in one step, costing ΔH_sub.');
});
gFus.css('cursor', 'pointer').on('click', function () {
  showPopup('Fusion', 'Melting Solid into Liquid costs the small enthalpy of fusion, ΔH_fus.');
});
gVap.css('cursor', 'pointer').on('click', function () {
  showPopup('Vaporization', 'Boiling Liquid into Gas costs the much larger enthalpy of vaporization, ΔH_vap.');
});
gTotal.css('cursor', 'pointer').on('click', function () {
  showPopup('Running total', 'The orange marker tracks the accumulated enthalpy along the two-step path. After both steps it reaches the Gas line: ΔH_fus + ΔH_vap = ΔH_sub.');
});

// ---- state rendering ----
// Every arrow is ALWAYS visible. The path select only dims the de-emphasized
// path and brightens the emphasized one — it never hides anything.
function render() {
  var direct = state.pathView === 'direct';
  var s = state.stepPath;

  // base opacity from emphasis
  var opEmph = 1, opDim = 0.25;
  var opSub = direct ? opEmph : opDim;
  var opFus = direct ? opDim : opEmph;
  var opVap = direct ? opDim : opEmph;

  // stepping overrides on the two-step path: light fusion then vaporization
  if (!direct && s !== 'idle') {
    var fusOn = (s === 'fusion' || s === 'vaporization' || s === 'done');
    var vapOn = (s === 'vaporization' || s === 'done');
    opFus = fusOn ? 1 : 0.25;
    opVap = vapOn ? 1 : 0.25;
  }
  // stepping on the direct path: done brightens the long arrow to full
  if (direct && s === 'done') opSub = 1;

  gSub.opacity(opSub);
  gFus.opacity(opFus);
  gVap.opacity(opVap);

  // running total — hidden entirely while idle
  if (s === 'idle') {
    gTotal.hide();
  } else {
    var yT = ySolid, label = '';
    if (!direct) {
      if (s === 'fusion') { yT = yLiquid; label = 'ΔH_fus'; }
      else { yT = yGas; label = 'ΔH_fus + ΔH_vap'; }
    } else {
      yT = yGas; label = 'ΔH_sub';
    }
    gTotal.show();
    totalLine.plot(axisX - 14, ySolid, axisX - 14, yT);
    totalTick.plot(axisX - 22, yT, axisX - 6, yT);
    totalTxt.text(label).move(axisX - 26, yT - 8);
  }

  document.getElementById('stepPathState').textContent = 'Path progress: ' + s;
}

// ---- interactions ----
function update_pathView(v) {
  state.pathView = v;
  // switching views resets the stepper so stale step states never linger
  state.stepPath = 'idle';
  render();
}
function setStepPath(v) {
  state.stepPath = v;
  render();
}
// View-aware stepper: two-step mode cycles idle → fusion → vaporization → done;
// direct mode jumps straight idle ↔ done as a single visible transition.
var stepOrderTwo = ['idle', 'fusion', 'vaporization', 'done'];
var stepOrderDirect = ['idle', 'done'];
function trigger_stepPath() {
  var order = (state.pathView === 'direct') ? stepOrderDirect : stepOrderTwo;
  var i = order.indexOf(state.stepPath);
  if (i < 0) i = 0;
  setStepPath(order[(i + 1) % order.length]);
}

// ---- demo step player ----
var demoSteps = [
  {
    title: 'Both paths at a glance',
    narration: 'All arrows are visible at once: the long Sublimation ΔH_sub arrow on the left and the stacked Fusion ΔH_fus + Vaporization ΔH_vap arrows on the right. The two-step path is emphasized; the direct arrow is dimmed but present, inviting comparison.',
    state: { pathView: 'two', stepPath: 'idle' }
  },
  {
    title: 'Fusion step',
    narration: 'Begin the two-step path: melting solid into liquid costs only the small fusion enthalpy, and the running total rises to the Liquid line.',
    state: { pathView: 'two', stepPath: 'fusion' }
  },
  {
    title: 'Add vaporization',
    narration: 'The vaporization arrow lights and the running total climbs the remaining large gap to the Gas line — the accumulated energy from both steps is complete.',
    state: { pathView: 'two', stepPath: 'done' }
  },
  {
    title: 'Compare with direct sublimation',
    narration: 'Emphasize the direct path: the two-step arrows dim and the single long sublimation arrow brightens. Stepping jumps straight from idle to done in one transition — it spans exactly the same height as the stacked arrows, proving ΔH_sub = ΔH_fus + ΔH_vap.',
    state: { pathView: 'direct', stepPath: 'done' }
  }
];
var stepIdx = 0;
function applyStep(i) {
  stepIdx = i;
  var st = demoSteps[i];
  document.getElementById('pathViewInput').value = st.state.pathView;
  state.pathView = st.state.pathView;
  setStepPath(st.state.stepPath);
  document.getElementById('demoNarration').textContent = st.narration;
  document.getElementById('stepLabel').textContent = (i + 1) + '/4: ' + st.title;
}
function nextStep() { if (stepIdx < demoSteps.length - 1) applyStep(stepIdx + 1); }
function prevStep() { if (stepIdx > 0) applyStep(stepIdx - 1); }

applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

Output ONLY the JSON evaluation object.

systemPrompt:
You are the orchestration agent for an iterative figure-generation loop. Generation works by taking an original static 2D figure, making a generation plan, generating an interactive 2D figure (SVG.js / Chart.js / Mermaid), and evaluating it.

You will receive the critic evaluation, including failure modes, scores, notes, and action items.
Your job is to decide which part of the system is most responsible for the problem:
- planner: the interaction plan or conceptual decomposition is wrong, incomplete, or missing the right elements
- generator: the plan is close to right, but the rendered implementation, labels, layout, interactivity, or execution is broken
- none: the figure is good enough to stop iterating

Use the failure modes and action items as the primary evidence. Do not decide from raw score thresholds alone.
Prefer planner when the critic indicates concept misunderstanding, missing core elements, wrong primitives, or the wrong overall interaction structure.
Prefer generator when the concept is right but the execution needs concrete implementation fixes like labels, wiring, geometry details, styling, or broken controls.

Return ONLY valid JSON with this exact shape:
{
	"next_step": "pass | fix_plan | refine_generation",
	"rationale": "one concise sentence explaining the decision"
}

CALIBRATION EXAMPLES — the decision turns on the failure modes, the five scores, and the notes, so only those are shown here.

